import { SDK_CODEGEN_VERSION } from '../../ir/schema.js';
import type { SdkIr, SdkProfileAttr, SdkEntity } from '../../ir/schema.js';

const FILE_HEADER = (irVersion: string, generatedAt: string) =>
  `# @bobsled-inc/sdk-codegen codegen_version=${SDK_CODEGEN_VERSION} ir_version=${irVersion}
# AUTO-GENERATED by @bobsled-inc/sdk-codegen.
# Do not edit. Regenerate via \`dogsled sdk generate --lang python\`.
# IR version: ${irVersion}
# Generated at: ${generatedAt}
`;

const QUALITY_MODULE_BODY = `from __future__ import annotations
from pydantic import BaseModel


class EntityQuality(BaseModel):
    confidence: float
    freshness_age_seconds: int
    source_diversity: int
    profile_coverage: float
`;

function pyTypeFor(attr: SdkProfileAttr): string {
  // Exhaustive switch so adding a new SdkAttrType enum variant in
  // ir/schema.ts is a compile error here, not a silent `object` fallthrough.
  let base: string;
  switch (attr.type) {
    case 'string':
    case 'timestamp':
      // Timestamps emit as ISO8601 strings.
      base = 'str';
      break;
    case 'number':
      base = 'float';
      break;
    case 'boolean':
      base = 'bool';
      break;
    case 'json':
      // JSON values may be objects, arrays, or primitives — `object` is
      // the broadest pyright-clean type (`Any` would defeat type checking).
      base = 'object';
      break;
    case 'vector':
      // Embedding columns emit as a list of floats. The host agent
      // reads `embedded_from` (provider/model) to generate matching query
      // embeddings.
      base = 'list[float]';
      break;
    default: {
      const _exhaustive: never = attr.type;
      throw new Error(`Unhandled SdkAttrType in Python emitter: ${String(_exhaustive)}`);
    }
  }
  return attr.nullable ? `Optional[${base}]` : base;
}

function emitEntityModule(entity: SdkEntity): string {
  const attrLines =
    entity.profile_attrs.length === 0
      ? '    # (no profile attrs declared)\n    pass'
      : entity.profile_attrs.map((attr) => `    ${attr.name}: ${pyTypeFor(attr)}`).join('\n');
  return `from __future__ import annotations
from typing import NewType, Optional
from pydantic import BaseModel
from ._quality import EntityQuality


${entity.branded_id_type} = NewType('${entity.branded_id_type}', str)


class ${entity.name}Profile(BaseModel):
    ${entity.primary_key}: ${entity.branded_id_type}
${attrLines}
    _quality: EntityQuality
`;
}

export interface EmitPythonOptions {
  generatedAt?: string;
}

export interface EmittedFile {
  path: string;
  content: string;
}

/**
 * Emit a Python SDK from the SDK IR.
 *
 * Returns a list of files (relative paths). Caller writes them to disk.
 * Targets pydantic v2 + Python `>=3.10`. `EntityQuality` lives in
 * `entities/_quality.py` and is imported per entity.
 */
export function emitPythonSdk(ir: SdkIr, options: EmitPythonOptions = {}): EmittedFile[] {
  const generatedAt = options.generatedAt ?? new Date().toISOString();
  const header = FILE_HEADER(ir.ir_version, generatedAt);

  const qualityFile: EmittedFile = {
    path: 'entities/_quality.py',
    content: header + '\n' + QUALITY_MODULE_BODY,
  };

  const entitiesInit: EmittedFile = {
    path: 'entities/__init__.py',
    content: header + '\n',
  };

  const entityFiles: EmittedFile[] = ir.entities.map((entity) => ({
    path: `entities/${entity.name}.py`,
    content: header + '\n' + emitEntityModule(entity),
  }));

  const initLines = [
    '# AUTO-GENERATED package init.',
    `from .entities._quality import EntityQuality`,
    ...ir.entities.map(
      (e) => `from .entities.${e.name} import ${e.name}Profile, ${e.branded_id_type}`
    ),
  ].join('\n');

  return [
    { path: '__init__.py', content: header + '\n' + initLines + '\n' },
    qualityFile,
    entitiesInit,
    ...entityFiles,
  ];
}
